+      <div style="font-size:17px;display:flex;align-items:center;gap:7px"><dc-import name="GramaireWordmark" hint-size="104px,20px" style="font-size:17px"></dc-import><span style="color:var(--fg-faint);font-weight:500">Lab</span></div>
