+    <div style="width:1px;height:18px;background:var(--border)"></div>
+    <div onClick="{{ toggleTheme }}" title="Toggle light / dark" class="gx-switch" style="cursor:pointer;width:46px;height:25px;border-radius:999px;background:var(--bg-2);border:1px solid var(--border-strong);position:relative;flex:none">
+      <span style="position:absolute;left:6px;top:50%;transform:translateY(-50%);font-size:11px;line-height:1;color:var(--fg-faint)">☀</span>
+      <span style="position:absolute;right:6px;top:50%;transform:translateY(-50%);font-size:10px;line-height:1;color:var(--fg-faint)">☾</span>
+      <span class="gx-switch-knob" style="position:absolute;top:2px;left:2px;width:19px;height:19px;border-radius:50%;background:var(--accent);box-shadow:0 1px 2px rgba(0,0,0,.35)"></span>
+    </div>
