+
+  <!-- body -->
+  <div style="flex:1;display:grid;grid-template-columns:minmax(360px,0.95fr) 1.05fr;min-height:0">
+
+    <!-- editor -->
+    <div style="display:flex;flex-direction:column;border-right:1px solid var(--border);min-height:0">
