+      <div style="flex:none;padding:9px 16px;border-top:1px solid var(--border);background:var(--bg-1);display:flex;gap:18px;font-family:var(--font-mono);font-size:11px;color:var(--fg-faint)">
+        <span>{{ stats.rules }} rules</span>
