+      </div>
+
+      <div style="padding:16px 18px 6px;flex:none">
+        <div style="font-family:var(--font-mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--fg-faint);margin-bottom:11px">rules — pick one to diagram</div>
+        {{ ruleChips }}
+      </div>
+
+      <div style="padding:14px 18px 22px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:center;min-height:170px;flex:none">
+        {{ diagram }}
+      </div>
+
+      <div style="padding:16px 18px;flex:none">
+        <div style="font-family:var(--font-mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--fg-faint);margin-bottom:12px">FIRST / FOLLOW — computed from the grammar</div>
+        {{ ffTable }}
+      </div>
+
+      <div style="margin-top:auto;flex:none;padding:11px 18px;background:var(--out-bg);color:var(--out-fg);font-family:var(--font-mono);font-size:12px;display:flex;align-items:center;gap:9px;position:sticky;bottom:0"><span style="color:#4ade80">✓</span>{{ checkLine }}</div>
