+</x-dc>
+<script type="text/x-dc" data-dc-script data-props="{&quot;theme&quot;:{&quot;editor&quot;:&quot;enum&quot;,&quot;options&quot;:[&quot;light&quot;,&quot;dark&quot;],&quot;default&quot;:&quot;light&quot;,&quot;tsType&quot;:&quot;'light'|'dark'&quot;,&quot;section&quot;:&quot;Theme&quot;}}">
+const EXAMPLES = {
+  calc: { file: "calc.gram.md", text:
+`# Calc — a small arithmetic grammar
+
+Expr
+  : Expr \`+\` Term   {% Add %}
+  | Expr \`-\` Term   {% Sub %}
+  | Term
+
+Term
+  : Term \`*\` Atom   {% Mul %}
+  | Term \`/\` Atom   {% Div %}
+  | Atom
+
+Atom
+  : \`(\` Expr \`)\`
+  | \`num\`
+` },
+  json: { file: "json.gram.md", text:
+`# JSON (RFC 8259), condensed
+
+Value
+  : Object
+  | Array
+  | \`string\`
+  | \`number\`
+  | \`true\`
+  | \`false\`
+  | \`null\`
+
+Object
+  : \`{\` Members \`}\`
+
+Array
+  : \`[\` Elements \`]\`
+` },
+  lr: { file: "lr.gram.md", text:
+`# lr — Gramaire's own notation, condensed
+
+Rule
+  : Name Alts
+
+Alts
+  : \`:\` Seq
+  | \`|\` Seq
+
+Seq
+  : Symbol Seq
+  | Symbol
+` },
+};
+
+class Component extends DCLogic {
+  state = { example: 'calc', text: EXAMPLES.calc.text, rule: 'Expr', theme: 'light' };
+
+  componentDidMount(){ this.applyTheme(); }
+  applyTheme(){ try { document.documentElement.setAttribute('data-theme', this.state.theme); } catch(e){} }
+  toggleTheme = () => this.setState(s => ({ theme: s.theme === 'dark' ? 'light' : 'dark' }), () => this.applyTheme());
+
+  loadExample = (name) => {
+    const ex = EXAMPLES[name]; if(!ex) return;
+    const rules = this.parse(ex.text);
+    this.setState({ example: name, text: ex.text, rule: rules[0] ? rules[0].name : '' });
+  };
+  onInput = (e) => {
+    const text = e.target.value;
+    const rules = this.parse(text);
+    const exists = rules.some(r => r.name === this.state.rule);
+    this.setState({ text, example: '', rule: exists ? this.state.rule : (rules[0] ? rules[0].name : '') });
+  };
+  selectRule = (name) => this.setState({ rule: name });
+
+  parse(text){
+    const lines = (text || '').split('\n');
+    const rules = []; let cur = null;
+    for(const raw of lines){
+      if(/^\s*#/.test(raw)) continue;
+      const t = raw.trim(); if(!t) continue;
+      if(t[0] === ':' || t[0] === '|'){
+        if(!cur) continue;
+        const body = t.slice(1).replace(/\{%[\s\S]*?%\}/g, '').trim();
+        const toks = (body.match(/`[^`]*`|\S+/g) || []).map(m =>
+          m[0] === '`' ? { type:'t', text: m.slice(1, -1) } : { type:'nt', text: m });
+        if(toks.length) cur.alts.push(toks);
+      } else {
+        const name = t.split(/\s+/)[0];
+        cur = { name, alts: [] }; rules.push(cur);
+      }
+    }
+    return rules;
+  }
+
+  analyze(rules){
+    const map = {}; const names = new Set();
+    rules.forEach(r => { map[r.name] = r; names.add(r.name); });
+    const isNT = (tok) => tok.type === 'nt' && names.has(tok.text);
+    const firstCache = {};
+    const first = (name, seen) => {
+      if(firstCache[name]) return firstCache[name];
+      seen = seen || new Set(); if(seen.has(name)) return new Set(); seen.add(name);
+      const out = new Set(); const r = map[name];
+      if(r){ r.alts.forEach(alt => {
+        const s = alt[0]; if(!s) return;
+        if(isNT(s)) first(s.text, seen).forEach(x => out.add(x));
+        else out.add(s.text);
+      }); }
+      firstCache[name] = out; return out;
+    };
+    const firstOf = (tok) => isNT(tok) ? first(tok.text) : new Set([tok.text]);
+    names.forEach(n => first(n));
+    // FOLLOW
+    const follow = {}; names.forEach(n => follow[n] = new Set());
+    if(rules[0]) follow[rules[0].name].add('$');
+    for(let pass = 0; pass < 8; pass++){
+      rules.forEach(r => { r.alts.forEach(alt => {
+        for(let i = 0; i < alt.length; i++){
+          const s = alt[i]; if(!isNT(s)) continue;
+          if(i < alt.length - 1) firstOf(alt[i + 1]).forEach(x => follow[s.text].add(x));
+          else follow[r.name].forEach(x => follow[s.text].add(x));
+        }
+      }); });
+    }
+    const terms = new Set();
+    rules.forEach(r => r.alts.forEach(alt => alt.forEach(tok => { if(!isNT(tok)) terms.add(tok.text); })));
+    return { map, names, isNT, first, follow, terms, rules };
+  }
+
+  tokW(tok){ const len = (tok.text || '').length; return tok.type === 't' ? Math.max(28, len * 8 + 16) : Math.max(46, len * 8 + 20); }
+
+  nodeEl(tok, x, y, w, key){
+    const R = React;
+    if(tok.type === 't'){
+      return R.createElement('g', { key }, [
+        R.createElement('rect', { key:'r', x, y: y - 14, width: w, height: 28, rx: 14, fill:'var(--bg-2)', stroke:'var(--border-strong)', strokeWidth:1.5 }),
+        R.createElement('text', { key:'t', x: x + w/2, y, textAnchor:'middle', dominantBaseline:'central', fill:'var(--t-term)', fontFamily:"'IBM Plex Mono', monospace", fontSize:13, fontWeight:600 }, tok.text),
+      ]);
+    }
+    const known = this._info && this._info.names.has(tok.text);
+    return R.createElement('g', { key, style:{ cursor: known ? 'pointer' : 'default' }, onClick: known ? () => this.selectRule(tok.text) : undefined }, [
+      R.createElement('rect', { key:'r', x, y: y - 15, width: w, height: 30, rx: 6, fill:'color-mix(in srgb, var(--accent) 8%, var(--bg))', stroke:'var(--accent)', strokeWidth:1.6 }),
+      R.createElement('text', { key:'t', x: x + w/2, y, textAnchor:'middle', dominantBaseline:'central', fill:'var(--accent)', fontFamily:"'IBM Plex Mono', monospace", fontSize:13, fontWeight:600 }, tok.text),
+    ]);
+  }
+
+  buildDiagram(rule){
+    const R = React;
+    if(!rule || !rule.alts.length)
+      return R.createElement('div', { style:{ color:'var(--fg-faint)', fontFamily:'var(--font-mono)', fontSize:'12px' } }, 'no productions');
+    const gap = 18, lead = 14, stroke = 'var(--fg-faint)';
+    const rows = rule.alts.map(alt => {
+      let x = 0; const nodes = alt.map(tok => { const w = this.tokW(tok); const n = { x, w, tok }; x += w + gap; return n; });
+      return { nodes, contentW: Math.max(0, x - gap) };
+    });
+    const maxC = Math.max(40, ...rows.map(r => r.contentW));
+    const LX = 46, contentX = LX + lead, RX = contentX + maxC + lead, startX = 16, endX = RX + 30, W = endX + 14;
+    const rowH = 52, topY = 28, H = topY + (rows.length - 1) * rowH + 26;
+    const kids = [];
+    const line = (d, key) => R.createElement('path', { key, d, fill:'none', stroke, strokeWidth:1.6, strokeLinecap:'round' });
+    rows.forEach((row, i) => {
+      const y = topY + i * rowH; let prevR = null;
+      row.nodes.forEach((n, j) => {
+        const nx = contentX + n.x;
+        if(j === 0){
+          if(i === 0) kids.push(line(`M${startX} ${y} H${nx}`, `ld${i}`));
+          else kids.push(line(`M${LX} ${topY} V${y - 9} Q${LX} ${y} ${LX + 9} ${y} H${nx}`, `ld${i}`));
+        } else kids.push(line(`M${prevR} ${y} H${nx}`, `c${i}-${j}`));
+        kids.push(this.nodeEl(n.tok, nx, y, n.w, `n${i}-${j}`));
+        prevR = nx + n.w;
+      });
+      if(prevR === null) prevR = (i === 0 ? startX : LX + 9);
+      if(i === 0) kids.push(line(`M${prevR} ${y} H${endX}`, `tl${i}`));
+      else kids.push(line(`M${prevR} ${y} H${RX - 9} Q${RX} ${y} ${RX} ${y - 9} V${topY}`, `tl${i}`));
+    });
+    kids.push(R.createElement('circle', { key:'s', cx: startX, cy: topY, r: 4, fill:'var(--accent)' }));
+    kids.push(R.createElement('circle', { key:'e', cx: endX, cy: topY, r: 4, fill:'var(--accent)' }));
+    return R.createElement('svg', { viewBox:`0 0 ${W} ${H}`, style:{ display:'block', width:'100%', maxWidth: W + 'px', height:'auto' } }, kids);
+  }
+
+  renderVals(){
+    const R = React;
+    const rules = this.parse(this.state.text);
+    const info = this.analyze(rules);
+    this._info = info;
+    const active = rules.find(r => r.name === this.state.rule) || rules[0];
+    const set = (s) => '{ ' + [...s].join(' ') + ' }';
+
+    const exampleTabs = R.createElement('div', { style:{ display:'flex', gap:6 } },
+      Object.keys(EXAMPLES).map(name => {
+        const on = this.state.example === name;
+        return R.createElement('span', {
+          key: name, onClick: () => this.loadExample(name),
+          style:{ fontFamily:'var(--font-mono)', fontSize:'12px', fontWeight: on ? 600 : 400,
+            color: on ? '#fff' : 'var(--fg-muted)', background: on ? 'var(--accent)' : 'var(--bg-2)',
+            padding:'5px 12px', borderRadius:'999px', cursor:'pointer' } }, name);
+      }));
+
+    const ruleChips = R.createElement('div', { style:{ display:'flex', flexWrap:'wrap', gap:7 } },
+      rules.map(r => {
+        const on = active && r.name === active.name;
+        return R.createElement('span', {
+          key: r.name, onClick: () => this.selectRule(r.name),
+          style:{ fontFamily:'var(--font-mono)', fontSize:'12.5px', fontWeight:600,
+            color: on ? 'var(--accent)' : 'var(--fg-muted)',
+            background: on ? 'color-mix(in srgb, var(--accent) 10%, var(--bg))' : 'var(--bg-2)',
+            border: '1px solid ' + (on ? 'var(--accent)' : 'var(--border)'),
+            padding:'5px 11px', borderRadius:'6px', cursor:'pointer' } }, r.name);
+      }));
+
+    const ffTable = R.createElement('div', { style:{ display:'flex', flexDirection:'column', gap:0, border:'1px solid var(--border)', borderRadius:'8px', overflow:'hidden' } },
+      rules.map((r, i) => R.createElement('div', {
+        key: r.name,
+        style:{ display:'grid', gridTemplateColumns:'92px 1fr 1fr', gap:'12px', alignItems:'center',
+          padding:'9px 14px', background: i % 2 ? 'var(--bg-1)' : 'var(--bg)',
+          borderTop: i ? '1px solid var(--border)' : 'none', fontFamily:'var(--font-mono)', fontSize:'12.5px' } }, [
+        R.createElement('span', { key:'n', onClick: () => this.selectRule(r.name),
+          style:{ color:'var(--accent)', fontWeight:600, cursor:'pointer' } }, r.name),
+        R.createElement('span', { key:'fi', style:{ color:'var(--fg-muted)' } }, [
+          R.createElement('span', { key:'l', style:{ color:'var(--fg-faint)', marginRight:'8px' } }, 'FIRST'),
+          R.createElement('span', { key:'v', style:{ color:'var(--t-term)' } }, set(info.first(r.name))) ]),
+        R.createElement('span', { key:'fo', style:{ color:'var(--fg-muted)' } }, [
+          R.createElement('span', { key:'l', style:{ color:'var(--fg-faint)', marginRight:'8px' } }, 'FOLLOW'),
+          R.createElement('span', { key:'v', style:{ color:'var(--t-term)' } }, set(info.follow[r.name] || new Set())) ]),
+      ])));
+
+    const leftRec = rules.some(r => r.alts.some(a => a[0] && info.isNT(a[0]) && a[0].text === r.name));
+
+    return {
+      text: this.state.text,
+      filename: EXAMPLES[this.state.example] ? EXAMPLES[this.state.example].file : 'untitled.gram.md',
+      onInput: this.onInput,
+      toggleTheme: this.toggleTheme,
+      method: 'IELR(1)',
+      rule: active ? active.name : '—',
+      conflictText: '● ' + info.names.size + ' rules · 0 conflicts',
+      checkLine: 'gramaire --check · clean · ' + (leftRec ? 'left-recursion resolved by IELR(1)' : 'tables locked'),
+      stats: { rules: info.names.size, terminals: info.terms.size },
+      exampleTabs, ruleChips, ffTable,
+      diagram: this.buildDiagram(active),
+    };
+  }
+}
+</script>
